import type { MultiSelectValuesProps } from "../multi-select.types";
import type { AvatarStackProps } from "@components/avatar-stack";

import React from "react";

import { MultiSelectClasses } from "../multi-select.styles";
import { useMultiSelect } from "../hooks/use-multi-select";

import { MultiSelectChip } from "./multi-select-chip";
import { MultiSelectChipCloseButton } from "./multi-select-chip-close-button";

export const MultiSelectValues: React.FC<MultiSelectValuesProps> = ({ children }) => {
  const { value, allOptions, placeholder, disabled } = useMultiSelect();

  let triggerItems;
  if (value.length === 0) {
    triggerItems = <>{placeholder}</>;
  } else if (typeof children === "function") {
    triggerItems = (
      <>
        {value.map((v) => {
          const option = allOptions.find((opt) => opt.value === v);
          return children({ value: v, option });
        })}
      </>
    );
  } else if (React.Children.count(children) > 0) {
    triggerItems = React.Children.map(children, (child) => {
      if (
        React.isValidElement<AvatarStackProps>(child) &&
        (child.type as { displayName?: string }).displayName === "AvatarStack"
      ) {
        return React.cloneElement(child, { ...child.props, size: "xsm" });
      }

      return child;
    });
  } else {
    triggerItems = (
      <>
        {value.map((v) => {
          const option = allOptions.find((opt) => opt.value === v);
          return (
            <MultiSelectChip key={v}>
              {option?.label}
              <MultiSelectChipCloseButton value={v} />
            </MultiSelectChip>
          );
        })}
      </>
    );
  }

  return (
    <div className={MultiSelectClasses.triggerItems} data-disabled={disabled}>
      {triggerItems}
    </div>
  );
};
MultiSelectValues.displayName = "MultiSelect.Values";
